439	/**
440	 * Saves the settings being changed, leaving the others as they are: a figure setting's value is
441	 * recorded from its from-date (the sheet's today when none is given), keeping the values recorded
442	 * from other dates and replacing one recorded from the same date. An action's entry in the
443	 * permission matrix is not dated: it replaces the one before, nor is the parent sheet, nor the alert threshold, nor the escalation gap.
444	 */
445	public class SaveSettings {
446	    public void save(@Val SettingsInput input, @Val Sheet sheet, SettingsRepository repository,
447	            net.officefloor.hq.app.sheet.SheetRepository sheets, Out<Settings> settingsOut) {
448	        if (input.parentChanged()) sheets.saveParent(sheet.id(), input.parent());
449	        Settings now = repository.find(sheet.id());
450	        if (input.policyDateChanged() || input.periodNumberingFromChanged() || input.graceDaysChanged()
451	                || input.entryDateChanged() || input.potChanged() || input.fiscalStartMonthChanged()
452	                || input.alertThresholdChanged() || input.escalateAfterChanged()) {
453	            repository.saveUndated(new Settings(sheet.id(), now.today(), now.dated(),
454	                    input.policyDateChanged() ? input.policyDate() : now.policyDate(),
455	                    input.periodNumberingFromChanged() ? input.periodNumberingFrom() : now.periodNumberingFrom(), now.perms(),
456	                    input.graceDaysChanged() ? input.graceDays() : now.graceDays(),
457	                    input.entryDateChanged() ? input.entryDate() : now.entryDate(),
458	                    input.potChanged() ? input.pot() : now.pot(),
459	                    input.fiscalStartMonthChanged() ? input.fiscalStartMonth() : now.fiscalStartMonth(),
460	                    input.alertThresholdChanged() ? input.alertThreshold() : now.alertThreshold(),
461	                    input.escalateAfterChanged() ? input.escalateAfter() : now.escalateAfter()));
462	        }
463	        input.perms().forEach((action, roles) -> repository.recordPerm(sheet.id(), action, roles));
464	        java.util.Map<String, String> values = new java.util.LinkedHashMap<>(input.datedValues());
465	        values.putAll(input.gradeTermsValues());
466	        values.putAll(input.gradeGraceValues());
467	        values.putAll(input.gradeProofThresholdValues());
468	        if (input.capValue() != null) values.put(Settings.CAP, input.capValue());
469	        if (input.proofThresholdValue() != null) values.put(Settings.PROOF_THRESHOLD, input.proofThresholdValue());
470	        if (input.noteThresholdValue() != null) values.put(Settings.NOTE_THRESHOLD, input.noteThresholdValue());
471	        if (input.roundingValue() != null) values.put(Settings.ROUNDING, input.roundingValue());
472	        if (input.reviewThresholdValue() != null) values.put(Settings.REVIEW_THRESHOLD, input.reviewThresholdValue());
473	        values.forEach((key, value) -> {
474	            LocalDate from = input.from().getOrDefault(key, sheet.today());
475	            repository.record(sheet.id(), key, from, value);
476	        });
477	        settingsOut.set(repository.find(sheet.id()));
478	    }
