// grace days (blank: off), past which an open period closes when today is changed, and each grade's
// grace days (blank: none), dated, past a claim's due-by before it is overdue, and each grade's proof threshold
// (blank: none, the sheet's), dated, in place of the sheet's for a claim of the grade, and its pot (blank:
// none), not dated, shared out as cuts among a balanced pool's members, and its parent sheet (blank: none), not
// dated, whose rates a grade takes on a date this sheet has none in force, and its fiscal year start month
// (1 to 12), not dated, and its alert threshold (blank: off), not dated, above which a person's due-total
// is alerted, and its rounding mode (half-up or half-even; blank: none, by the policy date), dated, by which
// a claim dated then rounds, and its review threshold (blank: none), dated, above which a claim's due on its
// date sends it to REVIEW instead of OPEN when it is opened, and its escalation gap in days (blank: off),
// not dated, at least which after a claim's previous reminder a reminder escalates it, once. Only the settings typed in (or stepped into)
// since the last save are sent, so saving one leaves the other as it is.
function SettingsForm({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const settings = useSettings(sheetId);
  const [fields, setFields] = useState<Omit<Settings, 'gradeTerms' | 'perms' | 'gradeGrace' | 'gradeProofThreshold'>>({
    cap: '',
    proofThreshold: '',
    noteThreshold: '',
    clerkLimit: '',
    floor: '',
    terms: '',
    latePct: '',
    policyDate: '',
    periodNumberingFrom: '',
    graceDays: '',
    entryDate: '',
    pot: '',
    parent: '',
    fiscalStartMonth: '',
    alertThreshold: '',
    rounding: '',
    reviewThreshold: '',
    escalateAfter: '',
  });
  const [touched, setTouched] = useState<Set<Key>>(new Set());
  const [gradeFields, setGradeFields] = useState<Record<string, string>>({});
      }
      body.rounding = rounding;
    }
    if (touched.has('reviewThreshold')) {
      const threshold = fields.reviewThreshold.trim();
      if (threshold !== '' && !REVIEW_THRESHOLD.test(threshold)) {
        setError('A review threshold is 0.00 or more, with up to two decimals, or blank.');
        return;
      }
      body.reviewThreshold = threshold;
    }
    if (touched.has('escalateAfter')) {
      const escalateAfter = fields.escalateAfter.trim();
      if (escalateAfter !== '' && !TERMS.test(escalateAfter)) {
        setError('An escalation gap is a whole number of days, 0 or more, or blank.');
        return;
      }
      body.escalateAfter = escalateAfter;
    }
    if (gradesTouched.size > 0) {
      const gradeTerms: Record<string, string> = {};
      for (const grade of GRADES) {
        if (!gradesTouched.has(grade)) continue;
        const terms = (gradeFields[grade] ?? '').trim();
        if (terms !== '' && !TERMS.test(terms)) {
          setError(`Terms for grade ${grade} are a whole number of days, 0 or more, or blank.`);
            onFocus={() => touch('reviewThreshold')}
            onChange={(e) => change('reviewThreshold', e.target.value)}
          />
        </label>{' '}
        {fromInput('review-threshold')}{' '}
        <span>
          now: <strong data-testid="setting-review-threshold-current">{settings.data?.reviewThreshold ?? ''}</strong>
        </span>{' '}
        <label>
          Escalate after days{' '}
          <input
            data-testid="setting-escalate-after"
            inputMode="numeric"
            placeholder="off"
            value={fields.escalateAfter}
            onFocus={() => touch('escalateAfter')}
            onChange={(e) => change('escalateAfter', e.target.value)}
          />
        </label>{' '}
        <span>
          now: <strong data-testid="setting-escalate-after-current">{settings.data?.escalateAfter ?? ''}</strong>
        </span>{' '}
        {ACTIONS.map((action) => (
          <span key={action}>
            <label>
              Who may {action}{' '}
  /** The pot, with two decimals ('' for none), not dated: shared out as cuts among a balanced pool's members. */
  pot: string;
  /** The parent sheet's id ('' for none), not dated: a grade with no rate in force on a date takes the parent's, up to three levels up. */
  parent: string;
  /** The fiscal year start month, 1 to 12 (1 unless set), not dated: a fiscal year FY<yyyy> starts on its first day in year yyyy. */
  fiscalStartMonth: string;
  /** The alert threshold, with two decimals ('' for off), not dated: a person whose due-total crosses above it is alerted. */
  alertThreshold: string;
  /** The rounding mode, half-up or half-even ('' for none: by the policy date), dated: a claim rounds by the one in force on its date. */
  rounding: string;
  /** The due above which a claim, on its date, goes to REVIEW instead of OPEN when it is opened ('' for none), dated. */
  reviewThreshold: string;
  /** The escalation gap in days ('' for off), not dated: a reminder at least that many days after the claim's previous one escalates it, once. */
  escalateAfter: string;
  /**
   * Every value recorded for each figure setting, by key (clerk-limit, floor, terms, late-pct,
   * terms-A, terms-B, terms-C, cap, proof-threshold, note-threshold, grace-A, grace-B, grace-C, proof-threshold-A, proof-threshold-B,
   * proof-threshold-C, rounding, review-threshold), in from-date order ('' for none). The values above are those
   * in force on the sheet's today.
   */
  dated?: Record<string, { from: string; value: string }[]>;
112:export function useSettings(sheetId: string) {
123:export function useFloor(sheetId: string): Dated {
137:export function useLate(sheetId: string): Late {
152:export function useCap(sheetId: string): string {
157:export function useRoles(sheetId: string) {
  /** The number of the claim it was split off; '' when it was not split off one. */
  splitFrom: string;
  /** The user whose open editor locks it on the sheet's today; '' when no one's does. */
  lockedBy: string;
  /** Whether it was added while its period was soft-closed. */
  lateEntry: boolean;
  /** The last sheet's today (yyyy-MM-dd) a reminder was written for it; '' when it was never reminded. */
  remindedOn: string;
  /** Its external reference, unique on the sheet regardless of case; '' when it has none. */
  ref: string;
  /** Its tags: trimmed, lower-cased, without repeats, sorted; empty when it has none. */
  tags: string[];
  /** The reason it was voided with, from the sheet's list; '' when none. */
  voidReason: string;
  /** Its comments, oldest first, as `<user> on <date>: <text>` (the sheet's today when written). */
  comments: string[];
  /** The number of the bulk settle batch that settled it; '' when none did (settled one at a time, or not settled). */
  batch: string;
  /** Its lines, oldest first, as `<label> <qty> x <unit>`; while it has any, its amount is their total. */
  lines: string[];
};

/** Whether a claim is a correction: it has no floor and no late charge. */
export const isCorrection = (c: Claim) => c.corrects !== '';

/** Whether a claim is open: OPEN, or PENDING a steward's approval. */
              <span data-testid="claim-corrects">{c.corrects}</span>{' '}
              <span data-testid="claim-ref">{c.ref}</span>{' '}
              <span data-testid="claim-tags">{c.tags.join(', ')}</span>{' '}
              <span data-testid="claim-opened-by">{c.openedBy}</span>{' '}
              <span data-testid="claim-stated">{c.stated ? 'yes' : 'no'}</span>{' '}
              <span data-testid="claim-period">{periodOf(periods, c.dueBy)?.name ?? ''}</span>{' '}
              <span data-testid="claim-due-by">{dueBy(c)}</span>{' '}
              <span data-testid="claim-overdue">{isOverdue(c, today, late, gradeOn(person.grades, c.date)) ? 'yes' : 'no'}</span>{' '}
              <span data-testid="claim-deferred">{showsDeferred(c, today) ? 'yes' : 'no'}</span>{' '}
              <span data-testid="claim-deferred-until">{c.deferredUntil}</span>{' '}
              <span data-testid="claim-proofs">{c.proofs}</span>{' '}
              <span data-testid="claim-split-from">{c.splitFrom}</span>{' '}
              <span data-testid="claim-late-entry">{c.lateEntry ? 'yes' : 'no'}</span>{' '}
